using System;using System.Reflection;
class MonoArchiveSmoke {static int Main(string[] args){try{var a=Assembly.LoadFrom(args[0]);var archive=a.GetType("DuelStructure.NativeLogArchive",true);var dto=a.GetType("DuelStructure.NativeLogArchive+Document",true);var document=Activator.CreateInstance(dto);dto.GetField("Point").SetValue(document,7);var bytes=(byte[])archive.GetMethod("Encode",BindingFlags.Public|BindingFlags.Static).Invoke(null,new[]{document});var restored=archive.GetMethod("Decode",BindingFlags.Public|BindingFlags.Static).Invoke(null,new object[]{bytes,7});if((int)dto.GetField("Point").GetValue(restored)!=7)throw new Exception("Archive point mismatch");Console.WriteLine("SUCCESS Mono history archive Newtonsoft/GZip roundtrip retains point and schema");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}
